"""Audit only actual native outputs and preserve every old pinned artifact."""
from run_aircraft_a29 import *
from audit_aircraft_a05 import vtk
from assess_aircraft_a23_reader_precision import printed_bound
import subprocess

def preserve():
    import audit_aircraft_a27 as previous
    s=inspect.getsource(previous.preserve).replace('preservation_A27','preservation_A29');ns=dict(globals());exec(compile(s,__file__+'::preserve','exec'),ns);ns['preserve']();dump(OUT/'preservation_reader_derivation.json',{'source':rel(Path(previous.__file__)),'source_sha256':streamsha(Path(previous.__file__)),'derived_source':s,'old_files_only_read':True})

def review():
    guard();dest=OUT/'composite_qualification_review.json';assert not dest.exists()
    candidate_summary=OUT/'native_case_summary_w4.json';assert candidate_summary.exists(),'Complete declared candidate before sealing';candidate=read(candidate_summary)['cases'];assert len(candidate)==15
    rows=[{'revision':d.parent.name,**read(d/'review.json')} for d in sorted(OUT.glob('w*/*')) if (d/'review.json').exists()];assert len(rows)==17
    samples=[];stress=[];cards=[];readback=[];starter_only=[]
    import test_aircraft_a29_law12 as candidate_runner
    for d in sorted(OUT.glob('w*/*')):
        g=read(d/'generation.json');rev=d.parent.name;n=g['name'];native_text=(d/(n+'_0000.rad')).read_text(encoding='utf-8');expected_card=candidate_runner.law12_card() if rev=='w4' else parent()['/MAT/LAW25/4'];cardpass='\n'.join(expected_card)+'\n' in native_text;cards.append({'revision':rev,'case':d.name,'material_card_identical_to_declared':cardpass,'known_mass_g':g['known_mass_g'],'volume_mm3':50,'density_g_mm3':.00183,'pass':bool(cardpass and abs(g['known_mass_g']-.0915)<1e-10)})
        if not (d/'review.json').exists():
            assert (d/'retained_failure.json').exists() and not (d/'engine.log').exists();starter_only.append({'revision':rev,'case':d.name,'starter_gate':read(d/'starter_gate.json'),'failure':read(d/'retained_failure.json'),'Engine_not_run':True});continue
        if rev in ['w3','w4']:readback.append({'revision':rev,'case':d.name,**read(d/'native_frame_gate.json')})
        X=np.asarray(g['nodes_mm']);native=sorted(p for p in d.glob(n+'A*') if re.fullmatch(re.escape(n)+r'A\d{3}',p.name));assert native
        for p in sorted(set([native[0],native[len(native)//2],native[-1]])):
            ad=OUT/'native_field_audit'/rev/d.name;ad.mkdir(parents=True,exist_ok=True);v=ad/(p.name+'.vtk');assert not v.exists();res=subprocess.run([str(RUNTIME/'anim_to_vtk_win64.exe'),str(p)],capture_output=True,text=True,check=True,timeout=120);v.write_text(res.stdout,encoding='utf-8');q=vtk(res.stdout);order=np.argsort(q['NODE_ID']);pts=q['points'].reshape(-1,3)[order];disp=q['Displacement'].reshape(-1,3)[order];vel=q['Velocity'].reshape(-1,3)[order];bound=printed_bound(pts)+printed_bound(disp)+4*np.finfo(np.float32).eps*np.maximum.reduce([abs(pts),abs(disp),abs(X)])+1e-8;checks={'ids':bool(np.array_equal(q['NODE_ID'][order],np.arange(1,len(X)+1))),'finite':bool(np.isfinite(pts).all() and np.isfinite(disp).all() and np.isfinite(vel).all()),'identity_with_printing_bound':bool(np.all(abs(pts-X-disp)<=bound)),'no_eroded_elements':bool(np.all(q['EROSION_STATUS']==1))};samples.append({'revision':rev,'case':d.name,'time_ms':q['time'],'native':rel(p),'native_sha256':streamsha(p),'vtk':rel(v),'vtk_sha256':streamsha(v),'checks':checks,'pass':all(checks.values())})
            if p==native[-1] and d.name.startswith('PATCH_'):
                S=q['3DELEM_Stress'].reshape(-1,3,3);s=3*(q['time']/.1)**2-2*(q['time']/.1)**3;stress.append({'revision':rev,'case':d.name,'time_ms':q['time'],'native_stress_MPa_mean':S.mean(axis=0).tolist(),'native_stress_MPa_min':S.min(axis=0).tolist(),'native_stress_MPa_max':S.max(axis=0).tolist(),'declared_full3D_stress_Voigt_MPa':(constitutive()@patch_strain(d.name)*s).tolist(),'qualification':'Diagnostic full3D comparison at actual output time, no new post-run threshold. w1 wrong axes retained separately, w3 correct axes but full3D reference failed.'})
    dump(OUT/'native_fields_review.json',{'created_utc':now(),'samples':samples,'pass':all(x['pass'] for x in samples),'old_solvers_rerun':0,'printing_bounds_not_physical_tolerance':True});dump(OUT/'material_readback_review.json',{'created_utc':now(),'cases':cards,'pass':all(x['pass'] for x in cards),'legacy_LAW25_unchanged':True,'LAW12_is_explicit_new_branch':True});dump(OUT/'native_frame_review.json',{'created_utc':now(),'cases':readback,'pass':all(x['pass'] for x in readback),'wrong_w1_retained':True,'w2_Starter_only_validation_error_retained':True});dump(OUT/'affine_native_stress_observation.json',{'created_utc':now(),'cases':stress,'legacy_LAW25_general_3D_equivalence_claimed':False});dump(OUT/'starter_only_failures.json',{'created_utc':now(),'cases':starter_only,'count':len(starter_only),'all_Engine_not_run':all(x['Engine_not_run'] for x in starter_only)})
    h=dict(np.load(OUT/'w4/FREE_ROTATION_Y_N12/histories_SI.npz'));h2=dict(np.load(OUT/'w4/FREE_ROTATION_Y_N12_HALF/histories_SI.npz'));mask=(h['time_ms']>=h2['time_ms'][0])&(h['time_ms']<=h2['time_ms'][-1]);T=h['time_ms'][mask];ld=float(np.linalg.norm(h['physical_L_kg_m2_s'][mask]-np.column_stack([np.interp(T,h2['time_ms'],h2['physical_L_kg_m2_s'][:,a]) for a in range(3)]),axis=1).max());ed=float(abs(h['total_J'][mask]-np.interp(T,h2['time_ms'],h2['total_J'])).max());ratio=float(np.median(h2['time_step_ms'][1:])/np.median(h['time_step_ms'][1:]));dt={'actual_dt_ratio':ratio,'physical_L_difference_kg_m2_s':ld,'energy_difference_J':ed,'checks':{'actually_shorter':ratio<.6,'L_converges':bool(ld<.002*np.linalg.norm(h['physical_L_kg_m2_s'][0])+1e-9),'energy_converges':bool(ed<.002*h['total_J'][0]+1e-7)}}
    mesh=[]
    for motion in ['MEMBRANE','BENDING']:
        a=read(OUT/'w4'/f'{motion}_N6/review.json');b=read(OUT/'w4'/f'{motion}_N12/review.json');diff=abs(a['native_elastic_comparison_J']-b['native_elastic_comparison_J'])/b['native_elastic_comparison_J'];mesh.append({'motion':motion,'difference_fraction':diff,'pass':diff<.05,'N6':a,'N12':b})
    C=constitutive();tensor={'global_stiffness_MPa':C.tolist(),'minimum_eigenvalue_MPa':float(np.linalg.eigvalsh(C).min()),'symmetric':bool(np.allclose(C,C.T)),'positive_definite':bool(np.linalg.eigvalsh(C).min()>0),'full3D_is_new_explicit_assumption':True,'scalar_source_inputs_unchanged':True,'transverse_Poisson_assumptions':[.25,.25],'shear_reference_uniform_G_no_Ashear':True,'no_known_damage_target':True};dump(OUT/'independent_tensor_review.json',tensor)
    dump(OUT/'configuration_metadata_addendum.json',{'created_utc':now(),'inherited_plate_fields':['formulation TYPE1 DKT','fracture inherited LAW2','yield324','branches w0 description'], 'status':'Stale explanatory fields inherited through old configurations, not effective inputs. Authoritative actual decks have TYPE6 Isolid18, LAW25 in w0-w3 and explicit LAW12 in w4. Mesh, material card, config hashes, sources and native readback prove actual executed settings. No old configuration rewritten.','old_configuration_mutation':False})
    checks={'candidate_all_native_gates':all(x['pass'] for x in candidate),'time_refinement':all(dt['checks'].values()),'spatial_mesh':all(x['pass'] for x in mesh),'native_fields':all(x['pass'] for x in samples),'native_frame':all(x['pass'] for x in readback),'material_readback':all(x['pass'] for x in cards),'positive_independent_tensor':tensor['positive_definite'] and tensor['symmetric']};dump(dest,{'created_utc':now(),'cases':rows,'candidate_revision':'w4','refinement':dt,'mesh':mesh,'checks':checks,'composite_prototype_pass':all(checks.values()),'free_scope_pass':all(x['pass'] for x in candidate if x['case'].startswith('FREE')),'affine_scope_pass':all(x['pass'] for x in candidate if x['case'].startswith('PATCH_')),'membrane_scope_pass':all(x['pass'] for x in candidate if x['case'].startswith('MEMBRANE')),'bending_scope_pass':all(x['pass'] for x in candidate if x['case'].startswith('BENDING')),'legacy_LAW25_full3D_reference_failed':True,'starter_only_failures':len(starter_only),'whole_insertion_ready':False,'physical_material_and_fracture_qualified':False,'objective1_complete':False});print({'A29_review':checks,'prototype_pass':all(checks.values())},flush=True)

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('action',choices=['preserve','review']);globals()[p.parse_args().action]()
